#!/usr/bin/env node
import { buildSite } from './generate';
import { serveSite } from './server';

export interface CliOptions {
  command: string | null;
  content: string;
  output: string;
  templates: string;
  port: number;
  help: boolean;
}

export function parseArgs(args: string[]): CliOptions {
  const options: CliOptions = {
    command: null,
    content: './content',
    output: './dist',
    templates: './templates',
    port: 3000,
    help: false,
  };

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === 'build' || arg === 'serve') {
      options.command = arg;
    } else if (arg === '--content' || arg === '-c') {
      options.content = args[i + 1] ?? options.content;
      if (args[i + 1] !== undefined) i += 1;
    } else if (arg.startsWith('--content=')) {
      options.content = arg.slice('--content='.length);
    } else if (arg === '--output' || arg === '-o') {
      options.output = args[i + 1] ?? options.output;
      if (args[i + 1] !== undefined) i += 1;
    } else if (arg.startsWith('--output=')) {
      options.output = arg.slice('--output='.length);
    } else if (arg === '--templates' || arg === '-t') {
      options.templates = args[i + 1] ?? options.templates;
      if (args[i + 1] !== undefined) i += 1;
    } else if (arg.startsWith('--templates=')) {
      options.templates = arg.slice('--templates='.length);
    } else if (arg === '--port' || arg === '-p') {
      const value = args[i + 1];
      if (value !== undefined) {
        const parsed = Number.parseInt(value, 10);
        if (!Number.isNaN(parsed)) options.port = parsed;
        i += 1;
      }
    } else if (arg.startsWith('--port=')) {
      const parsed = Number.parseInt(arg.slice('--port='.length), 10);
      if (!Number.isNaN(parsed)) options.port = parsed;
    } else if (arg === '--help' || arg === '-h') {
      options.help = true;
    }
  }

  return options;
}

export function printUsage(): string {
  return [
    'Usage: npx ssg <command> [options]',
    '',
    'Commands:',
    '  build   Build a static site from Markdown files.',
    '  serve   Start a development server with live reload.',
    '',
    'Options:',
    '  --content <dir>, -c <dir>  Markdown content directory (default: ./content)',
    '  --output <dir>,  -o <dir>  Output directory (default: ./dist)',
    '  --templates <dir>, -t <dir> Template directory (default: ./templates)',
    '  --port <port>,   -p <port> Port for the dev server (default: 3000)',
    '  --help, -h                 Show this help message',
  ].join('\n');
}

export async function run(argv: string[]): Promise<void> {
  const options = parseArgs(argv.slice(2));

  if (options.help || (options.command !== 'build' && options.command !== 'serve')) {
    process.stdout.write(`${printUsage()}\n`);
    return;
  }

  if (options.command === 'serve') {
    const devServer = await serveSite({
      content: options.content,
      output: options.output,
      templates: options.templates,
      port: options.port,
    });
    process.stdout.write(`Serving ${options.output} at http://localhost:${devServer.port}\n`);
    return;
  }

  const result = await buildSite(options.content, options.output, options.templates);
  process.stdout.write(`Built ${result.pages.length} page(s) into ${options.output}\n`);
}

if (require.main === module) {
  run(process.argv).catch((err: unknown) => {
    const message = err instanceof Error ? err.message : String(err);
    process.stderr.write(`${message}\n`);
    process.exitCode = 1;
  });
}

import http from 'http';
import { promises as fs } from 'fs';
import path from 'path';
import chokidar, { type FSWatcher } from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { buildSite } from './generate';

export interface ServeOptions {
  content: string;
  output: string;
  templates: string;
  port: number;
}

export interface DevServer {
  port: number;
  close(): Promise<void>;
}

const RELOAD_CLIENT = `<script>(function(){var s=new WebSocket('ws://'+location.host);s.onmessage=function(e){if(e.data==='reload')location.reload();};})();</script>`;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.mjs': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.webp': 'image/webp',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
};

export function injectReloadScript(html: string): string {
  if (html.includes('</body>')) {
    return html.replace('</body>', `${RELOAD_CLIENT}</body>`);
  }
  return `${html}${RELOAD_CLIENT}`;
}

export async function serveSite(options: ServeOptions): Promise<DevServer> {
  const { content, output, templates, port } = options;

  await buildSite(content, output, templates);

  const wss = new WebSocketServer({ noServer: true });

  const server = http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url ?? '/', 'http://localhost');
      let pathname = decodeURIComponent(url.pathname);
      if (pathname === '/') {
        pathname = '/index.html';
      }

      const root = path.resolve(output);
      const target = path.resolve(root, `.${pathname}`);
      if (target !== root && !target.startsWith(`${root}${path.sep}`)) {
        res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Forbidden');
        return;
      }

      const data = await fs.readFile(target);
      const ext = path.extname(target).toLowerCase();
      const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';

      if (ext === '.html') {
        res.writeHead(200, { 'Content-Type': contentType });
        res.end(injectReloadScript(data.toString('utf8')));
        return;
      }

      res.writeHead(200, { 'Content-Type': contentType });
      res.end(data);
    } catch {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
    }
  });

  server.on('upgrade', (req, socket, head) => {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  });

  const watcher: FSWatcher = chokidar.watch([content, templates], {
    ignoreInitial: true,
  });

  let rebuildTimer: NodeJS.Timeout | null = null;

  const broadcast = (message: string): void => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    }
  };

  const scheduleRebuild = (): void => {
    if (rebuildTimer) {
      clearTimeout(rebuildTimer);
    }
    rebuildTimer = setTimeout(() => {
      rebuildTimer = null;
      buildSite(content, output, templates)
        .then(() => broadcast('reload'))
        .catch(() => {
          /* ignore rebuild errors so the watcher keeps running */
        });
    }, 100);
  };

  watcher.on('add', scheduleRebuild);
  watcher.on('change', scheduleRebuild);
  watcher.on('unlink', scheduleRebuild);

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, () => {
      server.removeListener('error', reject);
      resolve();
    });
  });

  const address = server.address();
  const actualPort = typeof address === 'object' && address !== null ? address.port : port;

  return {
    port: actualPort,
    close: async (): Promise<void> => {
      if (rebuildTimer) {
        clearTimeout(rebuildTimer);
        rebuildTimer = null;
      }
      await watcher.close();
      for (const client of wss.clients) {
        client.terminate();
      }
      await new Promise<void>((resolve) => {
        wss.close(() => resolve());
      });
      await new Promise<void>((resolve, reject) => {
        server.close((err) => (err ? reject(err) : resolve()));
      });
    },
  };
}

